param([ValidateSet('gui','auto','start','stop','restart','install','uninstall','precompile')][string]$Action='gui')
$ErrorActionPreference='Stop'
$Root=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..')); $Ruby='C:\Ruby33-x64\bin\ruby.exe'; $Nginx='C:\nginx'; $Logs=Join-Path $Root 'log'; $Pids=Join-Path $Root 'tmp\pids'
$Startup=Join-Path ([Environment]::GetFolderPath('Startup')) 'ApontiTVStartup.vbs'; $Bat=Join-Path $PSScriptRoot 'aponti_tv.bat'; $EnvFile=Join-Path $Root 'config\windows_startup.env'
New-Item -ItemType Directory -Force -Path $Logs,$Pids | Out-Null
function Log($text){Add-Content (Join-Path $Logs 'windows_startup.log') "[$(Get-Date -Format 'dd/MM/yyyy HH:mm:ss')] $text"}
function Init-Environment {
  $env:RAILS_ENV='production'; $env:RACK_ENV='production'; $env:RAILS_SERVE_STATIC_FILES='true'; $env:RI_FORCE_PATH_FOR_DLL='1'; $env:RUBYLIB=Join-Path $Root 'ruby_overrides'
  $env:Path=((@('C:\Ruby33-x64\bin','C:\Ruby33-x64\lib\ruby\3.3.0\x64-mingw-ucrt','C:\Ruby33-x64\msys64\ucrt64\bin','C:\Ruby33-x64\msys64\usr\bin','C:\nginx','C:\nginx\ffmpeg\bin')+$env:Path)-join ';')
  if(Test-Path $EnvFile){Get-Content $EnvFile|ForEach-Object{if($_ -match '^\s*([^#][^=]*)=(.*)$'){[Environment]::SetEnvironmentVariable($matches[1].Trim(),$matches[2],'Process')}}}
  if(-not $env:SECRET_KEY_BASE){$secret=& $Ruby -e "require 'securerandom'; puts SecureRandom.hex(64)"; Add-Content $EnvFile "SECRET_KEY_BASE=$secret"; $env:SECRET_KEY_BASE=$secret}
}
function Port($number){Get-NetTCPConnection -LocalPort $number -State Listen -ErrorAction SilentlyContinue|Select-Object -First 1}
function Start-Nginx {if(Port 80){return};$exe=Join-Path $Nginx 'nginx.exe';if(!(Test-Path $exe)){throw "nginx.exe não encontrado em $Nginx"};Start-Process $exe -WorkingDirectory $Nginx -WindowStyle Hidden;Log 'Nginx iniciado'}
function Start-Rails {if(Port 3000){return};if(!(Test-Path $Ruby)){throw "Ruby não encontrado em $Ruby"};Remove-Item (Join-Path $Pids 'server.pid') -Force -ErrorAction SilentlyContinue;Start-Process $Ruby -ArgumentList 'bin\rails','server','-b','0.0.0.0','-e','production','-P','tmp\pids\aponti-tv.pid' -WorkingDirectory $Root -WindowStyle Hidden -RedirectStandardOutput (Join-Path $Logs 'rails_startup.out.log') -RedirectStandardError (Join-Path $Logs 'rails_startup.err.log');Log 'Rails iniciado'}
function Stop-Rails {$c=Port 3000;if($c){Stop-Process -Id $c.OwningProcess -Force -ErrorAction SilentlyContinue};Remove-Item (Join-Path $Pids 'server.pid'),(Join-Path $Pids 'aponti-tv.pid') -Force -ErrorAction SilentlyContinue;Log 'Rails encerrado'}
function Stop-Nginx {
  $exe=Join-Path $Nginx 'nginx.exe'
  if(Test-Path $exe){
    try { Start-Process $exe -ArgumentList '-s','quit' -WorkingDirectory $Nginx -WindowStyle Hidden -Wait | Out-Null }
    catch { Log "Aviso ao encerrar Nginx: $($_.Exception.Message)" }
  }
  Start-Sleep -Milliseconds 500
  Get-Process nginx -ErrorAction SilentlyContinue|Stop-Process -Force -ErrorAction SilentlyContinue
  Log 'Nginx encerrado'
}
function Start-All {Init-Environment;Start-Nginx;Start-Rails};function Stop-All {Stop-Rails;Stop-Nginx}
function Install-Auto {$escaped=$Bat.Replace('"','""');Set-Content $Startup "Set shell = CreateObject(`"WScript.Shell`")`r`nshell.Run `"cmd.exe /c `"`"$escaped`"`" tray`", 0, False" -Encoding ASCII;Log 'Inicialização automática ativada'}
function Remove-Auto {Remove-Item $Startup -Force -ErrorAction SilentlyContinue;Remove-Item (Join-Path ([Environment]::GetFolderPath('Startup')) 'ApontiTVStartup.cmd') -Force -ErrorAction SilentlyContinue;Log 'Inicialização automática desativada'}
Init-Environment
switch($Action){'auto'{Start-All;exit};'start'{Start-All;exit};'stop'{Stop-All;exit};'restart'{Stop-All;Start-Sleep 1;Start-All;exit};'install'{Install-Auto;exit};'uninstall'{Remove-Auto;exit};'precompile'{Push-Location $Root;try{& $Ruby bin\rails assets:precompile}finally{Pop-Location};exit $LASTEXITCODE}}
Add-Type -AssemblyName PresentationFramework,PresentationCore,WindowsBase
[xml]$xaml=@'
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" Title="Aponti TV • Servidor" Width="920" Height="650" MinWidth="760" MinHeight="540" WindowStartupLocation="CenterScreen" Background="#0B1020" Foreground="#F3F6FF" FontFamily="Segoe UI">
<Window.Resources><Style TargetType="Button"><Setter Property="Foreground" Value="#F3F6FF"/><Setter Property="Background" Value="#202A42"/><Setter Property="BorderBrush" Value="#34415F"/><Setter Property="Padding" Value="16,9"/><Setter Property="Margin" Value="0,0,8,8"/><Setter Property="Cursor" Value="Hand"/><Setter Property="FontWeight" Value="SemiBold"/></Style></Window.Resources>
<Grid Margin="26"><Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
<DockPanel Margin="0,0,0,22"><Border Width="52" Height="52" CornerRadius="14" Background="#6D5DFB" Margin="0,0,14,0"><TextBlock Text="▶" FontSize="23" HorizontalAlignment="Center" VerticalAlignment="Center"/></Border><StackPanel VerticalAlignment="Center"><TextBlock Text="Aponti TV" FontSize="25" FontWeight="Bold"/><TextBlock Text="Controle e diagnóstico do servidor" Foreground="#9EABC6" FontSize="13"/></StackPanel></DockPanel>
<Grid Grid.Row="1" Margin="0,0,0,18"><Grid.ColumnDefinitions><ColumnDefinition/><ColumnDefinition/><ColumnDefinition/></Grid.ColumnDefinitions>
<Border Grid.Column="0" Background="#141C30" BorderBrush="#283550" BorderThickness="1" CornerRadius="14" Padding="17" Margin="0,0,10,0"><StackPanel><TextBlock Text="RAILS" Foreground="#8997B5" FontSize="11" FontWeight="Bold"/><StackPanel Orientation="Horizontal" Margin="0,9,0,4"><Ellipse Name="RailsDot" Width="11" Height="11" Fill="#64748B" Margin="0,0,8,0"/><TextBlock Name="RailsStatus" Text="Verificando..." FontSize="16" FontWeight="SemiBold"/></StackPanel><TextBlock Name="RailsDetail" Foreground="#8997B5" FontSize="12"/></StackPanel></Border>
<Border Grid.Column="1" Background="#141C30" BorderBrush="#283550" BorderThickness="1" CornerRadius="14" Padding="17" Margin="5,0"><StackPanel><TextBlock Text="NGINX" Foreground="#8997B5" FontSize="11" FontWeight="Bold"/><StackPanel Orientation="Horizontal" Margin="0,9,0,4"><Ellipse Name="NginxDot" Width="11" Height="11" Fill="#64748B" Margin="0,0,8,0"/><TextBlock Name="NginxStatus" Text="Verificando..." FontSize="16" FontWeight="SemiBold"/></StackPanel><TextBlock Name="NginxDetail" Foreground="#8997B5" FontSize="12"/></StackPanel></Border>
<Border Grid.Column="2" Background="#141C30" BorderBrush="#283550" BorderThickness="1" CornerRadius="14" Padding="17" Margin="10,0,0,0"><StackPanel><TextBlock Text="INICIALIZAÇÃO" Foreground="#8997B5" FontSize="11" FontWeight="Bold"/><StackPanel Orientation="Horizontal" Margin="0,9,0,4"><Ellipse Name="AutoDot" Width="11" Height="11" Fill="#64748B" Margin="0,0,8,0"/><TextBlock Name="AutoStatus" Text="Verificando..." FontSize="16" FontWeight="SemiBold"/></StackPanel><TextBlock Text="Iniciar junto com o Windows" Foreground="#8997B5" FontSize="12"/></StackPanel></Border></Grid>
<WrapPanel Grid.Row="2" Margin="0,0,0,12"><Button Name="StartButton" Content="▶  Iniciar" Background="#315C46"/><Button Name="StopButton" Content="■  Parar" Background="#63343E"/><Button Name="RestartButton" Content="↻  Reiniciar"/><Button Name="OpenButton" Content="↗  Abrir sistema"/><Button Name="AssetsButton" Content="⚙  Precompilar assets"/><Button Name="AutoButton" Content="Inicialização automática"/></WrapPanel>
<Border Grid.Row="3" Background="#080D19" BorderBrush="#283550" BorderThickness="1" CornerRadius="13" Padding="15"><Grid><Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/></Grid.RowDefinitions><DockPanel Margin="0,0,0,10"><TextBlock Text="LOG DO SERVIDOR" Foreground="#8997B5" FontWeight="Bold" FontSize="11"/><Button Name="RefreshButton" Content="Atualizar" DockPanel.Dock="Right" Padding="10,4" Margin="0"/></DockPanel><TextBox Name="LogBox" Grid.Row="1" Background="Transparent" Foreground="#C9D3E8" BorderThickness="0" FontFamily="Consolas" FontSize="12" IsReadOnly="True" TextWrapping="NoWrap" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Auto"/></Grid></Border>
<TextBlock Name="Message" Grid.Row="4" Margin="2,12,0,0" Foreground="#9EABC6" Text="Pronto."/></Grid></Window>
'@
$window=[Windows.Markup.XamlReader]::Load((New-Object Xml.XmlNodeReader $xaml));function C($name){$window.FindName($name)}
$green=[Windows.Media.Brushes]::MediumSeaGreen;$gray=[Windows.Media.Brushes]::SlateGray
function Status {$r=Port 3000;$n=Port 80;$a=Test-Path $Startup;(C RailsDot).Fill=$(if($r){$green}else{$gray});(C RailsStatus).Text=$(if($r){'Em execução'}else{'Parado'});(C RailsDetail).Text=$(if($r){"Porta 3000 • PID $($r.OwningProcess)"}else{'Porta 3000 indisponível'});(C NginxDot).Fill=$(if($n){$green}else{$gray});(C NginxStatus).Text=$(if($n){'Em execução'}else{'Parado'});(C NginxDetail).Text=$(if($n){"Porta 80 • PID $($n.OwningProcess)"}else{'Porta 80 indisponível'});(C AutoDot).Fill=$(if($a){$green}else{$gray});(C AutoStatus).Text=$(if($a){'Ativada'}else{'Desativada'});(C AutoButton).Content=$(if($a){'Desativar inicialização'}else{'Ativar inicialização'})}
function Logs {$files=@('rails_startup.err.log','rails_startup.out.log','windows_startup.log','assets_precompile.log')|ForEach-Object{Join-Path $Logs $_}|Where-Object{Test-Path $_};$lines=foreach($f in $files){"-- $([IO.Path]::GetFileName($f)) --";Get-Content $f -Tail 40 -ErrorAction SilentlyContinue};(C LogBox).Text=$lines-join[Environment]::NewLine;(C LogBox).ScrollToEnd()}
function Run($label,[scriptblock]$work){try{(C Message).Text="$label...";$window.Cursor=[Windows.Input.Cursors]::Wait;&$work;(C Message).Text="$label concluído."}catch{(C Message).Text="Erro: $($_.Exception.Message)";[Windows.MessageBox]::Show($_.Exception.Message,'Aponti TV','OK','Error')|Out-Null}finally{$window.Cursor=[Windows.Input.Cursors]::Arrow;Status;Logs}}
(C StartButton).Add_Click({Run 'Iniciando serviços' {Start-All}});(C StopButton).Add_Click({Run 'Encerrando serviços' {Stop-All}});(C RestartButton).Add_Click({Run 'Reiniciando serviços' {Stop-All;Start-Sleep 1;Start-All}});(C OpenButton).Add_Click({Start-Process 'http://localhost/'});(C AssetsButton).Add_Click({Run 'Precompilando assets' {Push-Location $Root;try{&$Ruby bin\rails assets:precompile 2>&1|Add-Content (Join-Path $Logs 'assets_precompile.log')}finally{Pop-Location}}});(C AutoButton).Add_Click({Run 'Alterando inicialização' {if(Test-Path $Startup){Remove-Auto}else{Install-Auto}}});(C RefreshButton).Add_Click({Logs})
$timer=New-Object Windows.Threading.DispatcherTimer;$timer.Interval=[TimeSpan]::FromSeconds(2);$timer.Add_Tick({Status});$window.Add_Loaded({Status;Logs;$timer.Start()});$window.Add_Closed({$timer.Stop()});[void]$window.ShowDialog()
